"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["89665"],{99194(e){e.exports=JSON.parse('{"id":"F122","slug":"fi-number-4-percent","name":"Financial Independence Number and the 4% Rule","subject":"Personal Finance","section":"Personal Finance","topic":"Financial independence and the 4% rule","level":"Beginner","aliases":["financial independence","FIRE","4 percent rule","safe withdrawal rate","25 times expenses"],"formula":{"latex":"FI=\\\\frac{E}{w},\\\\quad n=\\\\frac{\\\\ln\\\\!\\\\left[(FI\\\\,r+s)/(P\\\\,r+s)\\\\right]}{\\\\ln(1+r)}","also":[],"text":"Financial independence number = annual spending / safe withdrawal rate (4% gives 25 x spending); Years to get there = ln[(FI x r + s) / (current portfolio x r + s)] / ln(1 + r), where s is the yearly saving and r is the real return"},"symbols":[{"symbol":"E","meaning":"Annual spending in retirement","unit":"money"},{"symbol":"w","meaning":"Safe withdrawal rate: share of the starting portfolio taken out in year one, then adjusted for inflation","unit":"percent"},{"symbol":"s","meaning":"Amount saved each year","unit":"money"},{"symbol":"r","meaning":"Real (after-inflation) return on the portfolio","unit":"per year"},{"symbol":"P","meaning":"Current portfolio","unit":"money"}],"when_to_use":"Use it to estimate how large a portfolio must be to fund spending, and how long saving will take. The 4% rule comes from historical US data for a 30-year retirement; a longer retirement, lower expected returns or high fees point to a lower rate such as 3 to 3.5%. It is a guide, not a guarantee, and it does not include pensions or taxes. Working in real terms keeps the arithmetic free of inflation.","worked_example":{"problem":"Annual spending is 36,000 and you assume a 4% withdrawal rate. You have 150,000, save 24,000 a year from an income of 80,000, and earn a real return of 5%.","inputs":{"e":36000,"w":4,"p":150000,"s":24000,"r":5,"inc":80000},"steps":[{"label":"FI number = spending / withdrawal rate","working":"36000 / 0.04","value":"900,000.00"},{"label":"Progress = portfolio / FI number","working":"150000 / 900000","value":"16.7%"},{"label":"Savings rate = saving / income","working":"24000 / 80000","value":"30.0%"},{"label":"Years to reach FI","working":"max(ln((900000 x 0.05+24000) / (150000 x 0.05+24000)) / ln(1+0.05), 0)","value":"16.1"},{"label":"FI number at a 3.5% withdrawal rate","working":"36000 / 0.035","value":"1,028,571.43"}],"answer":"The financial independence number is 900,000.00. You are 16.7% of the way there, saving 30.0% of your income. At this pace it takes 16.1 years. At a 3.5% withdrawal rate the number would be 1,028,571.43."},"calculator":{"available":true,"inputs":[{"id":"e","label":"Annual spending in retirement","unit":"money","type":"number","default":36000,"hint":""},{"id":"w","label":"Withdrawal rate","unit":"%","type":"number","default":4,"hint":""},{"id":"p","label":"Current portfolio","unit":"money","type":"number","default":150000,"hint":""},{"id":"s","label":"Yearly saving","unit":"money","type":"number","default":24000,"hint":""},{"id":"r","label":"Real return","unit":"%","type":"number","default":5,"hint":""},{"id":"inc","label":"Annual income","unit":"money","type":"number","default":80000,"hint":""}],"checks":[{"expr":"e>0 and w>0 and r>0 and s>0 and inc>0","message":"Enter values above zero."}],"steps":[{"id":"fi","label":"FI number = spending / withdrawal rate","expr":"e/w","format":"money"},{"id":"prog","label":"Progress = portfolio / FI number","expr":"p/fi","format":"pct1"},{"id":"sr","label":"Savings rate = saving / income","expr":"s/inc","format":"pct1"},{"id":"n","label":"Years to reach FI","expr":"max(ln((fi*r+s)/(p*r+s))/ln(1+r), 0)","format":"num1"},{"id":"fi35","label":"FI number at a 3.5% withdrawal rate","expr":"e/0.035","format":"money"}],"results":["fi","prog","n"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"fi":900000,"prog":0.16666666666666666,"sr":0.3,"n":16.071250673449,"fi35":1028571.4285714285}},"finder":{"finds":"The portfolio size that supports your spending and the years to reach it","needs":"Spending, withdrawal rate, portfolio, saving, real return"},"related":[{"slug":"retirement-nest-egg","name":"Retirement Nest Egg and Required Saving"},{"slug":"pv-growing-annuity","name":"Present Value of a Growing Annuity"},{"slug":"cagr","name":"Compound Annual Growth Rate (CAGR)"}],"related_ids":["F112","F017","F038"],"group":"Personal finance","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>F</mi><mi>I</mi><mo>=</mo><mfrac><mi>E</mi><mi>w</mi></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>n</mi><mo>=</mo><mfrac><mrow><mi>ln</mi><mo>\u2061</mo><mtext>\u2009\u2063</mtext><mrow><mo fence=\\"true\\">[</mo><mo stretchy=\\"false\\">(</mo><mi>F</mi><mi>I</mi><mtext>\u2009</mtext><mi>r</mi><mo>+</mo><mi>s</mi><mo stretchy=\\"false\\">)</mo><mi mathvariant=\\"normal\\">/</mi><mo stretchy=\\"false\\">(</mo><mi>P</mi><mtext>\u2009</mtext><mi>r</mi><mo>+</mo><mi>s</mi><mo stretchy=\\"false\\">)</mo><mo fence=\\"true\\">]</mo></mrow></mrow><mrow><mi>ln</mi><mo>\u2061</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><mo stretchy=\\"false\\">)</mo></mrow></mfrac></mrow><annotation encoding=\\"application/x-tex\\">FI=\\\\frac{E}{w},\\\\quad n=\\\\frac{\\\\ln\\\\!\\\\left[(FI\\\\,r+s)/(P\\\\,r+s)\\\\right]}{\\\\ln(1+r)}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"family-office-breakeven","name":"Family Office Break-Even Size"},"next":{"slug":"fd-explicit-step","name":"Finite Difference: Explicit Scheme Step and Stability"},"lesson":null,"total":522}')}}]);